<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import SiteDialog from '@/features/management-shared/SiteDialog.vue'
import { getAdminApi, roleLabel, type AdminRow } from './api'
const api=getAdminApi(), rows=ref<AdminRow[]>([]), query=ref(''), role=ref('teacher'), status=ref('all'), error=ref(''), busy=ref(false), loaded=ref(false), modal=ref(''), selected=ref<AdminRow>(), saved=ref('')
const form=ref({name:'',username:'',student_number:'',email:'',role:'teacher'})
const filtered=computed(()=>rows.value.filter(x=>x.role===role.value&&(status.value==='all'||x.is_active===(status.value==='active'))&&[x.name,x.username,x.student_number].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())))
async function load(){try{rows.value=(await api.get<{items:AdminRow[]}>('users/')).items;loaded.value=true}catch(e){error.value=(e as Error).message}}
onMounted(load)
function open(kind:string,row?:AdminRow){selected.value=row;modal.value=kind;error.value='';form.value={name:row?.name||'',username:row?.username||'',student_number:row?.student_number||'',email:row?.email||'',role:row?.role||role.value}}
async function submit(){busy.value=true;error.value='';try{const id=selected.value?.id;await api.post(modal.value==='create'?'users/':`users/${id}/${modal.value==='edit'?'update':modal.value}/`,modal.value==='status'?{is_active:!selected.value?.is_active}:modal.value==='password'?{confirmation:'reset'}:{...form.value});modal.value='';saved.value='账号变更已保存。';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template>
  <div class="eyebrow">ACCOUNTS / 账号管理</div><header class="heading"><div><h1>账号管理</h1><p>统一管理平台账号，清晰区分教师登录账号与学生学号。</p></div><button class="primary" @click="open('create')">＋ 新增{{ roleLabel(role) }}</button></header>
  <p v-if="error && !modal" role="alert" class="error-block">{{ error }}</p><p v-if="saved" role="status" class="policy-note">{{ saved }}</p>
  <div class="stats"><div v-for="r in ['teacher','student','admin']" :key="r" class="stat"><div class="stat-top">{{ roleLabel(r) }}账号</div><strong>{{ rows.filter(x=>x.role===r).length }}</strong><small>全平台账号</small></div><div class="stat"><div class="stat-top">已停用账号</div><strong>{{ rows.filter(x=>!x.is_active).length }}</strong><small>保留历史关联</small></div></div>
  <section class="card"><div class="tabs"><button v-for="r in ['teacher','student','admin']" :key="r" :class="{active:role===r}" @click="role=r">{{ roleLabel(r) }} <em>{{ rows.filter(x=>x.role===r).length }}</em></button></div><div class="toolbar"><div class="search"><input v-model="query" aria-label="搜索账号" placeholder="搜索姓名、登录账号或学号"></div><select v-model="status" aria-label="账号状态"><option value="all">全部状态</option><option value="active">启用中</option><option value="disabled">已停用</option></select></div><div class="table-scroll"><table><thead><tr><th>姓名</th><th>{{ role==='student'?'学号':'登录账号' }}</th><th>关联课程</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td><div class="person"><span class="avatar">{{ row.name?.slice(0,1) }}</span><div><strong>{{ row.name }}</strong><small>{{ row.email || '未填写邮箱' }}</small></div></div></td><td class="account">{{ role==='student'?row.student_number:row.username }}</td><td>{{ row.course_count ?? 0 }} 门课程</td><td><span class="badge" :class="{gray:!row.is_active}">{{ row.is_active?'启用中':'已停用' }}</span></td><td><button class="link" @click="open('edit',row)">编辑</button><button class="link" @click="open('password',row)">重置密码</button><button class="link" :class="{danger:row.is_active}" @click="open('status',row)">{{ row.is_active?'停用':'启用' }}</button></td></tr><tr v-if="!filtered.length"><td colspan="5" class="empty">{{ loaded?'没有匹配的账号。':'正在加载账号…' }}</td></tr></tbody></table></div><div class="table-footer">共 {{ filtered.length }} 个账号</div></section>
  <div class="policy-note"><div><strong>账号身份与课程授权分开管理</strong><br>停用保留教学与研究记录。协作教师的权限在所属课程中配置。</div></div>
  <SiteDialog :open="Boolean(modal)" :title="modal==='create'?'新增'+roleLabel(role):modal==='edit'?'编辑账号':modal==='password'?'重置密码':selected?.is_active?'停用账号':'启用账号'" :subtitle="selected?.name || '填写真实账号信息'" @close="modal=''"><form id="admin-user-form" class="form-grid" @submit.prevent="submit"><template v-if="modal==='create'||modal==='edit'"><label class="field">姓名<input v-model="form.name" name="name" required></label><label v-if="form.role!=='student'" class="field">登录账号<input v-model="form.username" name="username" required autocomplete="off"></label><label v-else class="field">学号<input v-model="form.student_number" name="student_number" required :disabled="modal==='edit'"></label><label class="field">邮箱<input v-model="form.email" name="email" type="email"></label></template><div v-if="modal==='create'||modal==='password'" class="policy-note"><div><strong>{{ modal==='password'?'确认重置为初始密码':'初始密码规则' }}</strong><p>所有角色均按 S + 登录账号设置初始密码，无需手动填写；登录后提醒修改。</p><p v-if="form.role==='student'">学生使用学号作为登录账号。</p><p v-if="modal==='password'">确认重置 {{ selected?.name }}（{{ form.role==='student'?form.student_number:form.username }}）的密码？</p></div></div><p v-if="modal==='status'">{{ selected?.is_active?'停用后该账号不能再登录，已有课程和历史记录保留。':'启用后恢复账号登录能力，课程授权保持不变。' }}</p><p v-if="error" role="alert" class="error-block">{{ error }}</p></form><template #footer><button @click="modal=''">取消</button><button class="primary" type="submit" form="admin-user-form" :disabled="busy">{{ busy?'正在保存…':modal==='password'?'确认重置':'确认保存' }}</button></template></SiteDialog>
</template>
